import {Chess} from 'chess.js';
import {SUPPLEMENT_SEEDS} from './aia-supplement-seeds';
export const TRACKS={opening:'Aperturas',tactics:'Táctica y cálculo',strategy:'Estrategia',endgame:'Finales'} as const;
export type Track=keyof typeof TRACKS;
export const LEVELS=[['Fundamentos','Hasta 600'],['Jugar con seguridad','600–1000'],['Construir un plan','1000–1400'],['Coordinar las piezas','1400–1800'],['Profundizar','1800–2000'],['Técnica avanzada','2000–2200'],['Perfeccionamiento','2200+']];
export type Exercise={id:string;level:number;track:Track;title:string;concept:string;task:string;explanation:string;hints:string[];fen?:string;line?:string[];accepted?:string[];options?:string[];answer?:number;wrong?:Record<string,string>};
export const CATALOG:Exercise[]=[];
function position(setup:string[]|string){const c=typeof setup==='string'?new Chess(setup):new Chess();if(Array.isArray(setup))setup.forEach(m=>c.move(m));return c.fen();}
function move(level:number,track:Track,title:string,concept:string,setup:string[]|string,task:string,line:string[],explanation:string,hints:string[],accepted?:string[],wrong?:Record<string,string>){CATALOG.push({id:`${track}-${level}-board`,level,track,title,concept,fen:position(setup),task,line,explanation,hints,accepted,wrong});}
function quiz(level:number,track:Track,title:string,concept:string,task:string,options:string[],answer:number,explanation:string,hints:string[]=[]){let n=0;while(CATALOG.some(e=>e.id===`${track}-${level}-concept-${n}`))n++;CATALOG.push({id:`${track}-${level}-concept-${n}`,level,track,title,concept,task,options,answer,explanation,hints:hints.length?hints:['Relaciona la decisión con el objetivo de la posición.',concept]});}
move(0,'opening','Ocupar el centro','Los peones centrales facilitan la salida de las piezas. Las casillas e4, d4, e5 y d5 forman el centro.',[],'Avanza dos casillas un peón central. Se aceptan e4 y d4.',['e4'],'e4 y d4 ocupan el centro y abren diagonales. No son las únicas aperturas válidas, pero cumplen este objetivo.',['Busca los peones de las columnas d y e.','Pueden avanzar dos casillas desde su posición inicial.'],['e4','d4']);
quiz(0,'opening','Desarrollar antes de atacar','Desarrollar significa sacar las piezas hacia casillas útiles.','¿Qué plan general facilita una apertura sana?',['Sacar varias veces la dama sin necesidad','Desarrollar piezas, luchar por el centro y proteger el rey','Mover solo los peones de los extremos'],1,'El centro y el desarrollo permiten coordinar las piezas; el enroque ayuda a proteger el rey.');
move(0,'tactics','Un caballo, dos destinos','El caballo se desplaza dos casillas en una dirección y una perpendicular; puede saltar piezas.',[],'Desarrolla uno de los caballos a c3 o f3.',['Nf3'],'Cf3 y Cc3 desarrollan una pieza y aumentan el control del centro.',['Busca los caballos de b1 y g1.','El destino puede ser c3 o f3.'],['Nf3','Nc3']);
quiz(0,'tactics','Jaque, mate y ahogado','En jaque hay que eliminar el ataque al rey. Si no hay jaque ni jugadas legales es ahogado.','No hay jaque, pero el jugador al turno no tiene ninguna jugada legal. ¿Resultado?',['Victoria para el rival','Tablas por ahogado','Se captura el rey'],1,'El ahogado es tablas. El rey no se captura; el mate exige que esté en jaque.');
quiz(0,'strategy','Valor y seguridad','Los valores orientativos son peón 1, caballo y alfil 3, torre 5 y dama 9. La seguridad del rey tiene prioridad.','¿Qué debes comprobar antes de mover?',['Solo si puedo dar jaque','Amenazas del rival y seguridad de mis piezas y rey','Solo cuántos peones tengo'],1,'Haz una pausa: jaques del rival, capturas y amenazas. Después comprueba qué deja de defender tu jugada.');
quiz(0,'strategy','Una pieza defendida','Una pieza está defendida cuando otra puede recapturar legalmente sobre su casilla.','¿Basta con que una pieza esté defendida para que cualquier intercambio sea bueno?',['Sí, siempre','No: hay que calcular capturas y recapturas','Sí, si la pieza es una dama'],1,'Una pieza defendida puede perder material por el valor de los intercambios o una clavada. Cuenta la secuencia completa.');
move(0,'endgame','Promocionar el peón','Al alcanzar la última fila, un peón se convierte en dama, torre, alfil o caballo.','7k/P7/8/8/8/8/8/7K w - - 0 1','Promociona en dama en a8.',['a8=Q+'],'El peón se convierte en dama y da jaque por la octava fila. La elección de pieza importa en otros finales.',['El peón avanza hacia la fila 8.','Elige dama en el selector de promoción.']);
quiz(0,'endgame','El rey también trabaja','En posiciones con pocas piezas, el rey puede apoyar peones, siempre fuera de las casillas atacadas.','En un final sin amenazas directas de mate, ¿qué suele ayudar?',['Dejar siempre el rey en una esquina','Activar el rey con seguridad','Mover solo la dama si no existe'],1,'La actividad del rey ayuda a escoltar peones y disputar casillas. Comprueba siempre las amenazas.');
move(1,'opening','Desarrollar en la Italiana','Tras e4 e5 y Cf3 Cc6, Ac4 desarrolla el alfil hacia la diagonal de f7.',['e4','e5','Nf3','Nc6'],'Practica la entrada en la Italiana: desarrolla el alfil a c4.',['Bc4'],'Ac4 desarrolla una pieza y controla d5 y f7. Ab5 y d4 también son aperturas buenas; aquí practicamos la Italiana.',['Busca el alfil de f1.','La diagonal es f1–e2–d3–c4.']);
quiz(1,'opening','El enroque','El enroque exige rey y torre sin mover, camino libre y que el rey no esté, pase ni termine en jaque.','¿Puedes enrocar si el rey debe pasar por una casilla atacada?',['Sí, si la torre no está atacada','No','Solo si es enroque largo'],1,'El rey no puede atravesar jaque. Que la torre esté atacada, por sí solo, no prohíbe el enroque.');
move(1,'tactics','Mate en una: última fila','Busca primero jaques y verifica todas las escapatorias.','6k1/5ppp/8/8/8/8/8/4R1K1 w - - 0 1','Encuentra el mate en una.',['Re8#'],'Te8 es mate: la torre controla la octava fila y los peones impiden las escapatorias del rey.',['¿Qué jaque puede dar la torre por la fila 8?','Comprueba f8, h8 y las casillas de la fila 7.']);
quiz(1,'tactics','Piezas indefensas','Una amenaza no desaparece porque prepares un ataque en el otro flanco.','Tu rival ataca una pieza tuya sin defensa. ¿Qué haces primero?',['Atacar un peón lejano sin calcular','Revisar defensa, retirada, cambio o contraataque concreto','Sacrificar la dama automáticamente'],1,'Revisa respuestas concretas. Un contraataque sirve si el cálculo demuestra que resuelve el problema.');
quiz(1,'strategy','La pieza menos activa','Antes de buscar un ataque, identifica qué pieza participa menos.','No hay amenazas urgentes. Tus torres siguen desconectadas y un alfil no ha salido. ¿Plan razonable?',['Completar desarrollo y conectar las torres','Mover la misma pieza al azar','Avanzar todos los peones del rey'],0,'Coordinar las piezas mejora la posición y prepara planes posteriores.');
quiz(1,'strategy','Intercambios con recaptura','Ganar una pieza exige contar lo que recupera el rival.','Un alfil de 3 captura un peón de 1 y después una torre rival captura ese alfil. Sin más jugadas, ¿balance?',['Ganas un peón sin coste','Pierdes aproximadamente 2 puntos de material','Ganas una torre'],1,'Has ganado un peón y perdido un alfil: 1 − 3 = −2. La torre rival sigue en el tablero.');
move(1,'endgame','Mate con rey y dama','El rey ayuda a quitar casillas de escape; la dama da el jaque final.','7k/8/5KQ1/8/8/8/8/8 w - - 0 1','Da mate en una con la dama.',['Qg7#'],'Dg7 es mate: la dama está protegida por el rey de f6 y cubre g8 y h7.',['Busca un jaque cerca del rey negro.','La dama puede ir a g7 protegida por tu rey.']);
quiz(1,'endgame','Evitar el ahogado','Con gran ventaja hay que dejar una jugada legal o dar mate.','Tu rival solo tiene rey. Tu próxima jugada no da jaque y le quita todas sus jugadas legales. ¿Qué sucede?',['Ganas por tener más material','Tablas por ahogado','Puedes mover otra vez'],1,'Revisa las casillas de escape antes de encerrar al rey. Más material no evita el ahogado.');
move(2,'opening','Romper el centro: Escocesa','d4 disputa el centro y abre líneas; tras la captura negra suele recapturar el caballo.',['e4','e5','Nf3','Nc6'],'Juega la ruptura de la Escocesa y recaptura con el caballo.',['d4','exd4','Nxd4'],'d4 exd4 Cxd4 abre el centro con desarrollo. Después debes vigilar el caballo y desarrollar el resto de piezas.',['El peón de d2 puede ir a d4.','Tras exd4, el caballo de f3 puede recapturar.']);
quiz(2,'opening','Apertura y medio juego','Una secuencia memorizada es útil cuando comprendes sus planes y sus cambios de estructura.','El rival se desvía de tu variante conocida. ¿Cómo decides?',['Continuar de memoria aunque pierda una pieza','Revisar amenazas, centro, desarrollo y estructura','Intentar volver a la variante con cualquier jugada'],1,'Evalúa la posición real. Las ideas de la apertura orientan, pero no sustituyen comprobar amenazas.');
move(2,'tactics','Doble ataque de caballo','Un doble ataque amenaza dos objetivos a la vez.','4k3/7r/8/3N4/8/8/8/4K3 w - - 0 1','Da jaque con el caballo y ataca también la torre.',['Nf6+'],'Cf6+ ataca el rey e8 y la torre h7. El jaque obliga a atender al rey antes de salvar la torre.',['La torre está en h7 y el rey en e8.','Busca una casilla desde la que el caballo ataque ambos.']);
quiz(2,'tactics','La clavada absoluta','Una pieza clavada al rey no puede moverse si descubre un jaque.','¿Qué distingue una clavada absoluta de una relativa?',['La absoluta tiene al rey detrás de la pieza clavada','La absoluta solo puede hacerla un caballo','En la relativa el rey puede ser capturado'],0,'La legalidad impide descubrir un ataque al propio rey. En una clavada relativa, moverse puede ser legal aunque costoso.');
quiz(2,'strategy','Columna abierta','Una columna abierta no contiene peones de ninguno de los bandos.','¿Dónde puede ganar actividad una torre?',['En una columna abierta con puntos de entrada','Siempre detrás de todos sus peones sin propósito','En una casilla donde se pierde sin compensación'],0,'La columna es un medio para entrar en la posición rival. Comprueba las casillas de entrada y la seguridad de la torre.');
quiz(2,'strategy','Casilla débil','Una casilla que no puede ser defendida por peones puede convertirse en un puesto avanzado.','Un caballo puede instalarse en una casilla central que los peones rivales ya no atacan. ¿Qué comprobarías?',['Solo el color de la casilla','Si está apoyado, puede ser cambiado y participa en el plan','Nada: cualquier caballo central gana'],1,'Un puesto avanzado debe ser sostenible y útil. Las piezas rivales todavía pueden cambiar al caballo.');
move(2,'endgame','Oposición directa','En este final, ocupar e5 frente al rey e7 gana la oposición: dos reyes en la misma columna separados por una casilla.','8/4k3/8/8/4K3/4P3/8/8 w - - 0 1','Ocupa e5 con el rey para conseguir oposición directa.',['Ke5'],'Re5 sitúa los reyes en e5 y e7 con e6 entre ambos. Juegan negras; no afirmamos que la oposición por sí sola gane cualquier final.',['Tu rey está en e4.','Busca la casilla de su misma columna que deja e6 entre los reyes.']);
quiz(2,'endgame','Peón pasado','Un peón pasado no tiene peones rivales delante en su columna ni en las adyacentes que puedan detenerlo por avance o captura.','¿Qué suele aumentar la fuerza de un peón pasado?',['Alejar todas las piezas propias sin calcular','Apoyarlo con rey y piezas y controlar su bloqueo','Avanzarlo siempre aunque se pierda'],1,'El apoyo y el control de las casillas de avance suelen ser más importantes que avanzar por impulso.');
move(3,'opening','La Española: cambiar la estructura','En la variante del cambio de la Española, Axc6 dxc6 modifica la estructura y concede la pareja de alfiles a negras.',['e4','e5','Nf3','Nc6','Bb5','a6'],'Practica el cambio en c6 y, tras la recaptura, enroca.',['Bxc6','dxc6','O-O'],'Axc6 dxc6 0-0 es una línea legal de la variante del cambio. Las negras aceptan peones doblados y conservan la pareja de alfiles.',['El alfil de b5 puede capturar en c6.','Tras la recaptura, protege el rey mediante 0-0.']);
quiz(3,'opening','Repertorio con sentido','Un repertorio incluye posiciones típicas, rupturas, planes y respuestas a desviaciones.','¿Qué estudiarías junto a las jugadas de tu apertura?',['Solo la profundidad máxima de memoria','Estructuras y planes de ambos bandos','Solo trampas de mate rápido'],1,'Las estructuras y planes explican qué hacer cuando acaba la teoría conocida.');
move(3,'tactics','Combinación de Legal','El cálculo de jaques puede justificar una pérdida aparente de dama. Esta es una posición concreta: no generalices el sacrificio.', ['e4','e5','Nf3','d6','Bc4','Bg4','Nc3','g6','Nxe5','Bxd1'],'Las negras han capturado la dama. Calcula y ejecuta el mate en dos.',['Bxf7+','Ke7','Nd5#'],'Axf7+ Re7 Cd5# es mate. El jaque fuerza Re7; el caballo coordina con el alfil.',['Busca primero un jaque de alfil.','Tras Axf7+ Re7, un caballo da el mate desde d5.']);
quiz(3,'tactics','Cálculo hasta una posición estable','Una variante no acaba necesariamente en tu primera captura.','Tu línea gana una torre, pero el rival tiene una recaptura con jaque. ¿Dónde paras el cálculo?',['Antes del jaque para conservar la impresión de ventaja','Después de resolver jaques y recapturas relevantes','Siempre tras una sola media jugada'],1,'Continúa hasta poder valorar una posición estable. Los jaques intermedios pueden cambiar el balance.');
quiz(3,'strategy','Alfil bueno y malo','Un alfil puede estar limitado por sus propios peones; aun así puede cumplir tareas defensivas esenciales.','Antes de cambiar tu alfil limitado, ¿qué compruebas?',['Sus tareas defensivas y qué piezas quedan','Solo su valor de 3 puntos','Que todos los cambios son favorables'],0,'Cambiar una pieza aparentemente mala puede dejar débiles peones o casillas que defendía.');
quiz(3,'strategy','Rupturas de peones','Una ruptura cambia contactos entre peones y puede abrir líneas para las piezas.','¿Cuándo conviene preparar una ruptura central?',['Cuando tus piezas pueden aprovechar las líneas y el cálculo lo permite','Siempre antes de desarrollar','Solo para deshacer cualquier peón doblado'],0,'Conecta estructura y actividad: anticipa qué columnas, diagonales y casillas se abren para ambos bandos.');
quiz(3,'endgame','Torres activas','En finales de torres la actividad y los jaques pueden compensar peones.','Vas un peón por debajo. ¿Qué opción merece examinarse?',['Defender pasivamente todo sin alternativas','Activar la torre y buscar contrajuego con jaques o peones pasados','Cambiar siempre al final de peones'],1,'La actividad puede ofrecer recursos. Cambiar torres exige evaluar por separado el final de peones resultante.');
quiz(3,'endgame','Torre y peón pasado','Una torre detrás de un peón pasado propio suele ganar espacio de acción a medida que el peón avanza.','¿Es «torre detrás del pasado» una regla sin excepciones?',['Sí, aunque permita mate','No: hay que comprobar posición concreta, jaques y rey','Solo se aplica con damas'],1,'Es una guía útil, no una garantía. La situación concreta y los recursos del rival prevalecen.');
move(4,'opening','Caro-Kann: desarrollar con estructura','En la variante del cambio, exd5 cxd5 transforma la estructura y abre la columna c para negras.', ['e4','c6','d4','d5'],'Cambia en d5 y después desarrolla el caballo de b1 a c3.',['exd5','cxd5','Nc3'],'exd5 cxd5 Cc3 desarrolla presionando d5. El plan depende del desarrollo negro y de las rupturas centrales.',['El peón e4 puede capturar en d5.','Después desarrolla el caballo de b1.']);
quiz(4,'opening','Preparar una novedad','Una desviación de la teoría exige justificar sus consecuencias prácticas.','¿Qué hace útil una novedad para tu repertorio?',['Ser desconocida aunque pierda forzadamente','Ser viable y conectar con planes que comprendes','Tener una valoración inventada'],1,'Contrasta legalidad, respuestas críticas y planes. No confundas sorpresa con solidez.');
quiz(4,'tactics','Jugada intermedia','Un zwischenzug interrumpe una recaptura esperada con una amenaza más urgente.','Tras una captura rival, ¿qué candidatos debes incluir?',['Solo la recaptura automática','Jaques, amenazas forzadas y recapturas','Cualquier jugada tranquila sin examinar amenazas'],1,'Un jaque intermedio puede cambiar qué pieza recuperas o la posición del rey. Calcula también las respuestas.');
quiz(4,'tactics','Sacrificio y compensación','Un sacrificio debe justificarse por variantes o compensación concreta: seguridad del rey, actividad, tiempos o peones.','No encuentras una continuación forzada tras sacrificar. ¿Qué haces?',['Lo llamas ganador por intuición','Comparas compensación duradera y recursos defensivos','Ignoras que tienes menos material'],1,'Separa ataque demostrable y compensación posicional. Expresa la incertidumbre si el cálculo no decide.');
quiz(4,'strategy','Profilaxis','La profilaxis incorpora a tu decisión el plan más útil del adversario.','¿Qué pregunta ayuda a una decisión profiláctica?',['¿Qué haría mi rival si pudiera mover de nuevo?','¿Cómo ignoro sus piezas?','¿Qué peón puedo mover sin pensar?'],0,'Identifica su idea y busca mejorar tu posición limitándola; no se trata de defender todas las amenazas imaginables.');
quiz(4,'strategy','Cambiar hacia un final','Simplificar cambia los factores que deciden la posición.','Antes de cambiar damas con un peón de más, ¿qué valoras?',['Reyes, actividad, estructura y final resultante','Solo la cantidad de material','Nada: todos los finales con un peón de más ganan'],0,'Un peón extra no garantiza victoria. Actividad y posibilidades de bloqueo pueden hacer que el cambio sea desfavorable.');
quiz(4,'endgame','Lucena: construir un puente','En posiciones de Lucena, el bando fuerte necesita proteger al rey de los jaques laterales para promover su peón.','¿Qué significa construir un puente?',['Usar la torre para interponerla ante jaques y liberar al rey','Dejar la torre en prise sin compensación','Encerrar al rey propio detrás de la torre rival'],0,'La torre corta los jaques en el momento adecuado. Su ejecución depende de la columna del peón y la disposición exacta.');
quiz(4,'endgame','Philidor: defensa','En la posición defensiva de Philidor de torre y peón, el rey bloquea por delante y la torre limita al rey rival desde la sexta fila relativa.','Tras el avance del peón que quita refugio al rey atacante, ¿qué recurso caracteriza la defensa?',['Jaques desde atrás con suficiente distancia','Cambiar siempre la torre por el peón','Retirar el rey de la casilla de promoción sin motivo'],0,'La transición a jaques desde atrás evita que el rey encuentre refugio delante del peón. No se aplica a cualquier final de torres.');
move(5,'opening','Siciliana abierta: recuperar y desarrollar','En la Siciliana abierta, d4 cxd4 Cxd4 cambia un peón central blanco por el peón c negro.', ['e4','c5','Nf3','d6'],'Entra en la Siciliana abierta y recaptura en d4.',['d4','cxd4','Nxd4'],'d4 cxd4 Cxd4 abre líneas y crea una estructura asimétrica. Analiza desarrollo, d5 y posibles ataques de ambos bandos.',['La ruptura central comienza con d4.','Tras cxd4, el caballo de f3 recupera en d4.']);
quiz(5,'opening','Del repertorio a la estructura','Las transposiciones pueden conducir a una misma estructura mediante órdenes distintos.','¿Cómo organizas un repertorio avanzado para comprenderlo?',['Solo por listas independientes sin conexiones','Por posiciones críticas, estructuras y órdenes de jugadas','Solo por el nombre del campeón que lo usa'],1,'Relaciona transposiciones y diferencias concretas del orden: tiempos, derechos de enroque y rupturas disponibles.');
quiz(5,'tactics','Árbol de variantes','Un árbol de cálculo comienza por candidatos y respuestas críticas, no por asumir cooperación del rival.','¿Qué respuesta rival debes priorizar al comprobar tu candidato?',['La que más facilite tu idea','La defensa más exigente, incluidos recursos intermedios','La primera jugada que se te ocurra'],1,'Busca la refutación de tu propia idea. Si sobrevive a las respuestas críticas, evalúa la posición final.');
quiz(5,'tactics','Horizonte de cálculo','Una evaluación provisional puede cambiar si quedan amenazas forzadas fuera de la línea calculada.','La última posición de tu cálculo incluye una pieza atacada y jaques disponibles. ¿Qué concluyes?',['La evaluación ya es definitiva','Debo extender las líneas críticas antes de valorar','Los jaques futuros no cuentan'],1,'No cierres la variante en medio de una secuencia táctica. Localiza un punto de evaluación suficientemente estable.');
quiz(5,'strategy','Dos debilidades','Atacar dos objetivos separados puede sobrecargar una defensa que sostiene uno solo.','El rival defiende tu único objetivo sin concesiones. ¿Qué plan considerarías?',['Crear un segundo objetivo y mejorar la coordinación','Cambiar al azar todas las piezas','Repetir amenazas idénticas sin cambiar nada'],0,'Obligar a repartir defensores puede permitir una penetración. Evita crear debilidades propias innecesarias.');
quiz(5,'strategy','Sacrificio posicional','El material puede cambiarse por ventajas duraderas, pero la compensación necesita una evaluación concreta.','¿Qué dato apoya un sacrificio de calidad posicional?',['Peones débiles, casillas, bloqueo y actividad duraderos','Únicamente que parece espectacular','Que siempre vale lo mismo una torre que un caballo'],0,'Valora qué desaparece, qué piezas quedan y si el rival puede neutralizar la compensación mediante cambios.');
quiz(5,'endgame','Zugzwang y triangulación','En zugzwang, tener que mover empeora la posición. La triangulación puede devolver una posición con el turno cambiado.','¿Para qué triangula el rey?',['Para perder un tiempo y transferir el turno en una posición útil','Para poder quedar en jaque','Para repetir siempre hasta ganar automáticamente'],0,'Verifica casillas disponibles y respuestas. La triangulación no existe en cualquier posición.');
quiz(5,'endgame','Fortaleza','Una fortaleza es una disposición defensiva que impide progresar al rival pese a su ventaja aparente.','¿Qué debe demostrar un plan de victoria contra una posible fortaleza?',['Una vía concreta para penetrar o forzar concesiones','Solo una gran ventaja material','Una cifra positiva sin continuación'],0,'Busca rupturas, entradas del rey y posibilidades de zugzwang. Una valoración aislada no explica cómo progresar.');
move(6,'opening','Orden crítico: Najdorf','Tras desarrollar Cf3 y cambiar en d4, las negras pueden elegir ...a6 para preparar expansión y limitar saltos a b5.', ['e4','c5','Nf3','d6','d4','cxd4','Nxd4','Nf6','Nc3'],'Juegan negras. Ejecuta ...a6, entrada en la Najdorf.',['a6'],'...a6 controla b5 y prepara opciones como ...e5 o ...b5. Es un ejercicio de repertorio; otras defensas sicilianas también son válidas.',['Juegan negras: observa el peón de a7.','La jugada característica es ...a6.']);
quiz(6,'opening','Evaluar una posición crítica','El trabajo avanzado combina cálculo, estructuras y comparación de candidatos.','Dos órdenes transponen salvo por un tiempo. ¿Qué debes comprobar?',['Si ese tiempo permite una ruptura o cambia una respuesta táctica','Nada: una estructura parecida siempre es idéntica','Solo el nombre de la variante'],0,'Turno, piezas, enroques y captura al paso forman parte de la posición. Las semejanzas no garantizan una transposición exacta.');
quiz(6,'tactics','Decidir cuándo parar','El cálculo humano tiene un presupuesto de tiempo. Se priorizan líneas que pueden cambiar la decisión.','En una posición crítica con poco tiempo, ¿qué enfoque es más sólido?',['Repartir todo el tiempo entre cada jugada legal','Elegir candidatos plausibles, buscar refutaciones y comparar finales','Mover la primera jugada espectacular'],1,'La selectividad exige comprobar amenazas y respuestas críticas, evitando tanto el cálculo caótico como la intuición sin contraste.');
quiz(6,'tactics','Contrastar el análisis','Un motor aporta variantes y evaluaciones de una posición concreta con una búsqueda concreta.','Una línea del motor mejora tu análisis. ¿Cómo conviertes eso en aprendizaje?',['Copiando solo la cifra','Explicando la idea, verificando la línea y comparándola con tu decisión','Atribuyendo al motor una intención psicológica'],1,'Identifica el cambio de evaluación, el recurso omitido y una regla transferible. Conserva el contexto de la búsqueda.');
quiz(6,'strategy','Ventajas pequeñas','Una ventaja pequeña puede requerir maniobras y evitar contrajuego antes de una transformación.','¿Qué mejora un plan técnico con ventaja leve?',['Mejorar la peor pieza, limitar contrajuego y preparar una transformación concreta','Forzar un sacrificio sin cálculo','Suponer que la ventaja se convierte sola'],0,'Formula objetivos verificables: casilla, cambio favorable o ruptura. Revisa de nuevo los recursos defensivos.');
quiz(6,'strategy','Análisis autónomo','Separar tu análisis del contraste posterior permite localizar fallos reales de pensamiento.','¿Qué secuencia ayuda a revisar una partida propia?',['Motor primero y memorizar la mejor jugada sin preguntar','Análisis propio, posiciones críticas, contraste y ejercicio de corrección','Mirar solo el resultado'],1,'Registra qué pensaste, qué omitiste y qué comprobarás la próxima vez. El resultado de la partida no mide cada decisión.');
quiz(6,'endgame','Finales y tablas exactas','Las bases de finales resuelven posiciones dentro de su cobertura; hay que distinguir victoria teórica y viabilidad bajo la regla de 50 jugadas.','¿Qué revisarías al interpretar una tabla de finales?',['Posición exacta, turno, métrica y regla de 50 jugadas','Solo la cantidad de peones','Una posición parecida de memoria'],0,'WDL y distancias como DTZ responden preguntas diferentes. El estado exacto y las reglas aplicables importan.');
quiz(6,'endgame','Convertir una ventaja','Los cambios modifican las posibilidades de bloqueo, carreras y actividad del rey.','Antes de entrar en una carrera de peones, ¿qué calculas?',['Tiempos de promoción, jaques, coronación con amenaza y posición de los reyes','Solo quién tiene más peones','Solo la distancia de mi peón'],0,'Calcula ambos bandos hasta una posición estable, incluyendo promociones con jaque y posibles sacrificios para ganar tiempos.');
