for(const [level,track,title] of [[4,'tactics','Jugada intermedia'],[5,'tactics','Árbol de variantes'],[6,'tactics','Decidir cuándo parar'],[4,'endgame','Lucena: construir un puente'],[5,'endgame','Zugzwang y triangulación']] as const){const i=CATALOG.findIndex(e=>e.level===level&&e.track===track&&e.title===title);if(i>=0)CATALOG.splice(i,1);}
move(4,'tactics','Mate ahogado: desviar la torre','Un sacrificio de dama puede forzar a una torre a ocupar la última casilla de escape del rey. Calcula las respuestas antes de sacrificar.','5r1k/6pp/7N/8/2Q5/8/8/6K1 w - - 0 1','Encuentra la secuencia de mate en dos.',['Qg8+','Rxg8','Nf7#'],'Dg8+ obliga a Txg8: el rey no puede capturar porque el caballo h6 protege g8. Cf7# da mate al rey encerrado por sus propias piezas.',['Busca un jaque de dama en una casilla protegida por el caballo.','Tras Dg8+ Txg8, el caballo puede dar mate desde f7.']);
move(5,'tactics','La partida de la Ópera: coordinación','La actividad de las piezas y las líneas abiertas pueden justificar un sacrificio de dama. Aquí el rey negro carece de casillas útiles.', ['e4','e5','Nf3','d6','d4','Bg4','dxe5','Bxf3','Qxf3','dxe5','Bc4','Nf6','Qb3','Qe7','Nc3','c6','Bg5','b5','Nxb5','cxb5','Bxb5+','Nbd7','O-O-O','Rd8','Rxd7','Rxd7','Rd1','Qe6','Bxd7+','Nxd7'],'Calcula y ejecuta el mate en dos.',['Qb8+','Nxb8','Rd8#'],'Db8+ desvía al caballo d7 a b8. Td8# aprovecha la columna d y el control del alfil g5 sobre d8. Posición histórica de Morphy, 1858.',['El caballo d7 bloquea la columna de la torre.','Un jaque de dama en b8 obliga al caballo a abandonar d7.']);
move(6,'tactics','La Siempreviva: calcular hasta el mate','El cálculo forzado debe continuar tras el sacrificio y comprobar cada escape del rey. La coordinación decide esta posición concreta.', ['e4','e5','Nf3','Nc6','Bc4','Bc5','b4','Bxb4','c3','Ba5','d4','exd4','O-O','d3','Qb3','Qf6','e5','Qg6','Re1','Nge7','Ba3','b5','Qxb5','Rb8','Qa4','Bb6','Nbd2','Bb7','Ne4','Qf5','Bxd3','Qh5','Nf6+','gxf6','exf6','Rg8','Rad1','Qxf3','Rxe7+','Nxe7'],'Encuentra y juega la secuencia de mate en cuatro.',['Qxd7+','Kxd7','Bf5+','Ke8','Bd7+','Kf8','Bxe7#'],'Dxd7+ Rxd7 Af5+ Re8 Ad7+ Rf8 Axe7# coordina alfiles y torre. Estudiamos la defensa preparada de esta variante histórica, no afirmamos que cualquier respuesta tenga la misma duración.',['Empieza con un jaque que fuerce al rey a capturar tu dama.','Después usa jaques del alfil de d3; el otro alfil termina en e7.']);
move(4,'endgame','Lucena: preparar el puente','Una disposición de Lucena permite preparar una torre en la cuarta fila para interponerla ante futuros jaques laterales.','1K6/1P2k3/8/8/8/8/8/r2R4 w - - 0 1','Coloca la torre de d1 en d4 para preparar el puente antes de sacar el rey.',['Rd4'],'Td4 prepara una futura interposición en la cuarta fila. Es el primer paso del procedimiento; el ejercicio no da por completada la conversión del final.',['La torre debe subir por la columna d.','La cuarta fila es la altura del puente que vamos a preparar.']);
move(5,'endgame','Saavedra: evitar una trampa de ahogado','En esta posición, coronar en dama permite ...Tc4+ Dxc4 y ahogado. Una torre no controla las mismas casillas y conserva la posibilidad de ganar.','8/2P5/8/8/3r4/8/2K5/k7 w - - 0 1','Promociona en torre para evitar la defensa de ahogado y amenazar Ta8 mate.',['c8=R'],'c8=T amenaza Ta8#. Tras ...Tc4+ Txc4 no hay ahogado: el rey negro conserva a2. Con dama en c4, a2 está controlada y las otras salidas las controla el rey c2.',['Compara las casillas que controlan dama y torre desde c4.','Promociona el peón c7 en torre.']);

